const N = {{n}};
const bad = Math.floor(Math.random() * N);
let lo = 0, hi = N - 1, steps = 0;
const marks = [];
while (lo < hi) {
  const mid = (lo + hi) >> 1;
  steps++;
  marks.push(mid);
  if (mid >= bad) hi = mid; else lo = mid + 1;
}
ctx.clearRect(0, 0, W(), H());
ctx.fillStyle = '#1f2937'; ctx.fillRect(16, 60, W() - 32, 16);
ctx.fillStyle = '#f87171'; ctx.fillRect(16 + (bad / N) * (W() - 32), 56, 3, 24);
marks.forEach((m, i) => {
  ctx.fillStyle = 'rgba(96,165,250,' + (0.3 + (i / marks.length) * 0.7) + ')';
  ctx.fillRect(16 + (m / N) * (W() - 32), 84 + i * 3, 2, 2);
});
ctx.fillStyle = '#eee'; ctx.font = '15px system-ui';
ctx.fillText('커밋 ' + N.toLocaleString() + '개 · 범인을 ' + steps + '번 만에 좁혔다', 16, 34);
ctx.fillStyle = '#9ca3af'; ctx.font = '12px system-ui';
ctx.fillText('하나씩 보면 평균 ' + Math.round(N / 2).toLocaleString() + '번 — 그래서 bisect 를 쓴다', 16, H() - 14);

